import 'package:flutter/material.dart';
import '../models/case_model.dart';
import '../services/database_helper.dart';
import 'add_case_screen.dart';
import 'deadline_calculator_screen.dart';

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

    @override
      State<HomeScreen> createState() => _HomeScreenState();
      }

      class _HomeScreenState extends State<HomeScreen> {
        late Future<List<LegalCase>> _casesList;

          @override
            void initState() {
                super.initState();
                    _refreshCases();
                      }

                        void _refreshCases() {
                            setState(() {
                                  _casesList = DatabaseHelper.instance.getCases();
                                      });
                                        }

                                          @override
                                            Widget build(BuildContext context) {
                                                return Scaffold(
                                                      appBar: AppBar(
                                                              title: const Text('المحامي الرقمي - جدول الجلسات'),
                                                                      backgroundColor: const Color(0xFF1A237E),
                                                                              centerTitle: true,
                                                                                      actions: [
                                                                                                // زر حاسبة المهل القانونية في الشريط العلوي
                                                                                                          IconButton(
                                                                                                                      icon: const Icon(Icons.calculate_outlined, color: Colors.white),
                                                                                                                                  tooltip: 'حاسبة المهل القانونية',
                                                                                                                                              onPressed: () {
                                                                                                                                                            Navigator.push(
                                                                                                                                                                            context,
                                                                                                                                                                                            MaterialPageRoute(builder: (context) => const DeadlineCalculatorScreen()),
                                                                                                                                                                                                          );
                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                    body: FutureBuilder<List<LegalCase>>(
                                                                                                                                                                                                                                                            future: _casesList,
                                                                                                                                                                                                                                                                    builder: (context, snapshot) {
                                                                                                                                                                                                                                                                              if (snapshot.connectionState == ConnectionState.waiting) {
                                                                                                                                                                                                                                                                                          return const Center(child: CircularProgressIndicator());
                                                                                                                                                                                                                                                                                                    } else if (!snapshot.hasData || snapshot.data!.isEmpty) {
                                                                                                                                                                                                                                                                                                                return const Center(
                                                                                                                                                                                                                                                                                                                              child: Text(
                                                                                                                                                                                                                                                                                                                                              'لا يوجد جلسات مسجلة حالياً.\nاضغط على (+) لإضافة جلسة جديدة.',
                                                                                                                                                                                                                                                                                                                                                              textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                                                              style: TextStyle(fontSize: 16, color: Colors.grey),
                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                            final cases = snapshot.data!;
                                                                                                                                                                                                                                                                                                                                                                                                                                      return ListView.builder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                  itemCount: cases.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                              itemBuilder: (context, index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final legalCase = cases[index];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return Card(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: ListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title: Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '${legalCase.courtName} - قضية رقم: ${legalCase.caseNumber}',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style: const TextStyle(fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        subtitle: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            crossAxisAlignment: CrossAxisAlignment.start,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Text('الموكل: ${legalCase.clientName}'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Text('التاريخ: ${legalCase.hearingDate.toString().split(' ')[0]}'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (legalCase.postponementReason != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'سبب التأجيل: ${legalCase.postponementReason}',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style: const TextStyle(color: Colors.brown),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    floatingActionButton: FloatingActionButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onPressed: () async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final result = await Navigator.push(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              MaterialPageRoute(builder: (context) => const AddCaseScreen()),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (result == true) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              _refreshCases();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        backgroundColor: const Color(0xFF1A237E),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: const Icon(Icons.add, color: Colors.white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            